device.kernel:
({
  create({ sr, dsp }) {
    const max = sr * 3;
    const dl = dsp.delay(max), dr = dsp.delay(max);
    const tl = dsp.onepole(), tr = dsp.onepole();
    const time = dsp.smooth(60, 0);
    let first = true;
    return {
      process(L, R, n, p, t) {
        const target = Math.min(max - 4, 0.75 * 60 / t.bpm * sr);   // a dotted eighth, from the song's tempo
        if (first) { time.reset(target); first = false; }
        tl.set(p.tone); tr.set(p.tone);
        const fb = p.feedback / 100, wet = dsp.dB(p.level);
        for (let i = 0; i < n; i++) {
          const d = time.tick(target);
          const yl = dl.read(d), yr = dr.read(d);
          dl.write(L[i] + tl.lp(yl) * fb);
          dr.write(R[i] + tr.lp(yr) * fb);
          L[i] += yl * wet;
          R[i] += yr * wet;
        }
      },
    };
  },
})
